const countryCodes=["ad", "ae", "af", "ag", "ai", "al", "am", "ao", "aq", "ar", "as", "at", "au", "aw", "ax", "az", "ba", "bb", "bd", "be", "bf", "bg", "bh", "bi", "bj", "bl", "bm", "bn", "bo", "bq", "br", "bs", "bt", "bv", "bw", "by", "bz", "ca", "cc", "cd", "cf", "cg", "ch", "ci", "ck", "cl", "cm", "cn", "co", "cp", "cr", "cu", "cv", "cw", "cx", "cy", "cz", "de", "dg", "dj", "dk", "dm", "do", "dz", "ec", "ee", "eg", "eh", "er", "es", "et", "eu", "fi", "fj", "fk", "fm", "fo", "fr", "ga", "gb", "gb-eng", "gb-sct", "gb-wls", "gd", "ge", "gf", "gg", "gh", "gi", "gl", "gm", "gn", "gp", "gq", "gr", "gs", "gt", "gu", "gw", "gy", "hk", "hm", "hn", "hr", "ht", "hu", "ic", "id", "ie", "il", "im", "in", "io", "iq", "ir", "is", "it", "je", "jm", "jo", "jp", "ke", "kg", "kh", "ki", "km", "kn", "kp", "kr", "kw", "ky", "kz", "la", "lb", "lc", "li", "lk", "lr", "ls", "lt", "lu", "lv", "ly", "ma", "mc", "md", "me", "mf", "mg", "mh", "mk", "ml", "mm", "mn", "mo", "mp", "mq", "mr", "ms", "mt", "mu", "mv", "mw", "mx", "my", "mz", "na", "nc", "ne", "nf", "ng", "ni", "nl", "no", "np", "nr", "nu", "nz", "om", "pa", "pc", "pe", "pf", "pg", "ph", "pk", "pl", "pm", "pn", "pr", "ps", "pt", "pw", "py", "qa", "re", "ro", "rs", "ru", "rw", "sa", "sb", "sc", "sd", "se", "sg", "sh", "si", "sj", "sk", "sl", "sm", "sn", "so", "sr", "ss", "st", "sv", "sx", "sy", "sz", "tc", "td", "tf", "tg", "th", "tj", "tk", "tl", "tm", "tn", "to", "tr", "tt", "tv", "tw", "tz", "ua", "ug", "um", "un", "us", "uy", "uz", "va", "vc", "ve", "vg", "vi", "vn", "vu", "wf", "ws", "xk", "xx", "ye", "yt", "za", "zm", "zw"];
const countryNames=new Intl.DisplayNames(['pt-PT'],{type:'region'});
const specialCountries={'gb-eng':'Inglaterra','gb-sct':'Escócia','gb-wls':'País de Gales','xk':'Kosovo'};
const countryName=code=>specialCountries[code]||countryNames.of(code.toUpperCase());
const normalizeCountry=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[\u{1F1E6}-\u{1F1FF}]/gu,'').toLowerCase().trim();
const countryLookup=new Map();
for(const code of countryCodes){countryLookup.set(code,code);countryLookup.set(normalizeCountry(countryName(code)),code);if(code.length===2)for(const locale of ['en','fr','de'])countryLookup.set(normalizeCountry(new Intl.DisplayNames([locale],{type:'region'}).of(code.toUpperCase())),code);}
for(const [alias,code] of Object.entries({usa:'us',eua:'us',uk:'gb',sui:'ch',por:'pt',portuguesa:'pt',portugues:'pt',suica:'ch',suico:'ch',britanica:'gb',inglesa:'gb-eng',escocesa:'gb-sct',gales:'gb-wls',brasileira:'br',francesa:'fr',alemao:'de',alema:'de',espanhola:'es',italiana:'it','costa do marfim':'ci','republica checa':'cz','turquia':'tr','estados unidos da america':'us'}))countryLookup.set(alias,code);
function resolveCountry(value){const flag=String(value||'').match(/[\u{1F1E6}-\u{1F1FF}]{2}/u);if(flag){let code=[...flag[0]].map(c=>String.fromCharCode(c.codePointAt(0)-0x1f1e6+97)).join('');if(countryCodes.includes(code))return code;}return countryLookup.get(normalizeCountry(value));}
function countryOptions(){return countryCodes.map(code=>countryName(code)).sort((a,b)=>a.localeCompare(b,'pt')).map(name=>`<option value="${esc(name)}"></option>`).join('');}
function flagEmoji(code){const special={'gb-eng':'🏴','gb-sct':'🏴','gb-wls':'🏴','xk':'🇽🇰','xx':'🏳️','un':'🇺🇳','eu':'🇪🇺'};if(special[code])return special[code];if(!/^[a-z]{2}$/.test(code))return '🏳️';return [...code.toUpperCase()].map(c=>String.fromCodePoint(0x1F1E6+c.charCodeAt(0)-65)).join('');}
function flagAsset(code){if(typeof window!=='undefined'&&window.__HM_FLAG_DATA&&window.__HM_FLAG_DATA[code])return window.__HM_FLAG_DATA[code];return `flags/${encodeURIComponent(code)}.svg`;}
function countryFlag(value){const code=resolveCountry(value);if(!code)return `<span class="muted" title="${value?'Selecciona um país reconhecido na nacionalidade':'Nacionalidade por preencher'}" aria-label="Nacionalidade por identificar">—</span>`;const name=countryName(code);return `<span class="country-flag-wrap" role="img" aria-label="${esc(name)}" title="${esc(name)}"><img class="country-flag" src="${esc(flagAsset(code))}" alt="Bandeira de ${esc(name)}"></span>`;}
